'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '../../../lib/AuthContext';
import BasicInfo from './components/BasicInfo';
import ProjectDetails from './components/ProjectDetails';
import ModelsPricing from './components/ModelsPricing';
import AmenitiesFeatures from './components/AmenitiesFeatures';
import ReviewSubmit from './components/ReviewSubmit';
import { UserIcon, AcademicCapIcon, BriefcaseIcon, PhotoIcon, ClipboardDocumentListIcon, CheckCircleIcon } from '@heroicons/react/24/outline';
import { supabase } from '../../../lib/supabase';

// Define the project form data interface
export interface ProjectFormData {
  // Basic Information
  name: string;
  developer_id: string;
  city_id: string;
  locality_id: string;
  possession_status: 'Ready to Move' | 'Under Construction';
  project_size: {
    total_area: number;
    unit: string;
    built_up_area: number;
  };
  price_range: {
    min: number;
    max: number;
    currency: string;
  };
  emi_details: {
    amount: number;
    duration: number;
    interest_rate: number;
  };
  location_coordinates: {
    latitude: number;
    longitude: number;
  };

  // Project Details
  project_highlights: string[];
  description: string;
  brochure_url: string;

  // Models & Pricing
  models: Array<{
    bhk_type: string;
    super_built_up_area: number;
    carpet_area: number;
    price: number;
    price_unit: string;
    price_per_sqft: number;
    price_per_sqft_unit: string;
    availability_status: 'available' | 'sold_out' | 'coming_soon';
    specifications: {
      bedrooms: number;
      bathrooms: number;
      balconies: number;
      parking: number;
    };
  }>;

  // Amenities & Features
  amenities: string[]; // Array of amenity IDs
}

const initialFormData: ProjectFormData = {
  name: '',
  developer_id: '',
  city_id: '',
  locality_id: '',
  possession_status: 'Under Construction',
  project_size: {
    total_area: 0,
    unit: 'sq.ft.',
    built_up_area: 0,
  },
  price_range: {
    min: 0,
    max: 0,
    currency: 'INR',
  },
  emi_details: {
    amount: 0,
    duration: 0,
    interest_rate: 0,
  },
  location_coordinates: {
    latitude: 0,
    longitude: 0,
  },
  project_highlights: [],
  description: '',
  brochure_url: '',
  models: [],
  amenities: [],
};

const stepLabels = [
  { label: 'Basic Info', subtitle: 'Project basics' },
  { label: 'Project Details', subtitle: 'Details & highlights' },
  { label: 'Models & Pricing', subtitle: 'BHKs & pricing' },
  { label: 'Amenities', subtitle: 'Select amenities' },
  { label: 'Review', subtitle: 'Final review' },
];

export default function CreateProject() {
  const router = useRouter();
  const { user } = useAuth();
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState<ProjectFormData>(initialFormData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const totalSteps = 5;
  const progressPercent = ((currentStep - 1) / (stepLabels.length - 1)) * 100;

  const updateFormData = (data: Partial<ProjectFormData>) => {
    setFormData(prev => ({ ...prev, ...data }));
  };

  const handleNext = () => {
    if (currentStep < totalSteps) {
      setCurrentStep(prev => prev + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 1) {
      setCurrentStep(prev => prev - 1);
    }
  };

  const handleSubmit = async () => {
    if (!user) {
      setError('You must be logged in to create a project');
      return;
    }

    setLoading(true);
    setError(null);
    try {
      // Create project record with user_id
      const { data: projectData, error: projectError } = await supabase
        .from('projects')
        .insert({
          name: formData.name,
          developer_id: formData.developer_id,
          city_id: formData.city_id, 
          locality_id: formData.locality_id,
          possession_status: formData.possession_status,
          total_area: formData.project_size.total_area,
          area_unit: formData.project_size.unit,
          built_up_area: formData.project_size.built_up_area,
          price_min: formData.price_range.min,
          price_max: formData.price_range.max,
          price_currency: formData.price_range.currency,
          description: formData.description,
          brochure_url: formData.brochure_url,
          latitude: formData.location_coordinates.latitude,
          longitude: formData.location_coordinates.longitude,
          created_by: user.id,
          updated_by: user.id,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          status: 'active'
        })
        .select()
        .single();

      if (projectError) {
        throw new Error(`Failed to create project: ${projectError.message}`);
      }

      const projectId = projectData.id;

      // Create project highlights
      if (formData.project_highlights.length > 0) {
        const highlightsToInsert = formData.project_highlights.map(highlight => ({
          project_id: projectId,
          highlight: highlight,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        }));

        const { error: highlightsError } = await supabase
          .from('project_highlights')
          .insert(highlightsToInsert);

        if (highlightsError) {
          console.error('Error creating project highlights:', highlightsError);
        }
      }

      // Create project EMI details
      const { error: emiError } = await supabase
        .from('project_emi_details')
        .insert({
          project_id: projectId,
          amount: formData.emi_details.amount,
          duration_years: formData.emi_details.duration,
          interest_rate: formData.emi_details.interest_rate,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        });

      if (emiError) {
        console.error('Error creating EMI details:', emiError);
      }

      // Create project models
      if (formData.models.length > 0) {
        const modelsToInsert = formData.models.map(model => ({
          project_id: projectId,
          bhk_type: model.bhk_type,
          super_built_up_area: model.super_built_up_area,
          carpet_area: model.carpet_area,
          price: model.price,
          price_unit: model.price_unit || 'INR',
          price_per_sqft: model.price_per_sqft,
          price_per_sqft_unit: model.price_per_sqft_unit || 'INR',
          availability_status: model.availability_status,
          bedrooms: model.specifications.bedrooms,
          bathrooms: model.specifications.bathrooms,
          balconies: model.specifications.balconies,
          parking: model.specifications.parking,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        }));

        const { error: modelsError } = await supabase
          .from('project_models')
          .insert(modelsToInsert);

        if (modelsError) {
          console.error('Error creating project models:', modelsError);
        }
      }

      // Create project amenities
      if (formData.amenities.length > 0) {
        const amenitiesToInsert = formData.amenities.map(amenityId => ({
          project_id: projectId,
          amenity_id: amenityId,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        }));

        const { error: amenitiesError } = await supabase
          .from('project_amenities')
          .insert(amenitiesToInsert);

        if (amenitiesError) {
          console.error('Error creating project amenities:', amenitiesError);
        }
      }

      setMessage({ type: 'success', text: 'Project created successfully! Redirecting to projects page...' });
      setTimeout(() => {
        router.push('/dashboard/projects');
      }, 2000);
    } catch (err) {
      console.error('Error creating project:', err);
      setError(err instanceof Error ? err.message : 'Failed to create project');
      setMessage({ type: 'error', text: 'Failed to create project. Please try again.' });
    } finally {
      setLoading(false);
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return (
          <BasicInfo
            formData={formData}
            updateFormData={updateFormData}
            onNext={handleNext}
          />
        );
      case 2:
        return (
          <ProjectDetails
            formData={formData}
            updateFormData={updateFormData}
            onNext={handleNext}
            onBack={handleBack}
          />
        );
      case 3:
        return (
          <ModelsPricing
            formData={formData}
            updateFormData={updateFormData}
            onNext={handleNext}
            onBack={handleBack}
          />
        );
      case 4:
        return (
          <AmenitiesFeatures
            formData={formData}
            updateFormData={updateFormData}
            onNext={handleNext}
            onBack={handleBack}
          />
        );
      case 5:
        return (
          <ReviewSubmit
            formData={formData}
            onSubmit={handleSubmit}
            onBack={handleBack}
            loading={loading}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center py-8">
      {/* Modern Horizontal Progress Bar */}
      <div className="w-full max-w-2xl mb-8 relative">
        {/* Progress Track */}
        <div className="absolute top-6 left-0 right-0 h-1 bg-gray-200 rounded-full" />
        {/* Progress Fill */}
        <div
          className="absolute top-6 left-0 h-1 bg-green-500 rounded-full transition-all duration-300"
          style={{ width: `${progressPercent}%` }}
        />
        <ol className="flex items-center justify-between w-full relative z-10">
          {stepLabels.map((step, idx) => {
            const isActive = currentStep === idx + 1;
            const isCompleted = currentStep > idx + 1;
            return (
              <li key={step.label} className="flex-1 flex flex-col items-center">
                <div className="flex items-center justify-center">
                  <span
                    className={`flex items-center justify-center w-6 h-6 rounded-full border-2 text-xs font-bold transition-colors duration-200
                      ${isActive ? 'bg-green-500 border-green-500 text-white' : isCompleted ? 'bg-green-500 border-green-500 text-white' : 'bg-white border-gray-300 text-gray-400'}`}
                  >
                    {isCompleted ? (
                      <span className="w-3 h-3 bg-white rounded-full block" />
                    ) : (
                      idx + 1
                    )}
                  </span>
                </div>
                <span className={`mt-2 text-sm font-semibold ${isActive ? 'text-green-700' : 'text-gray-500'}`}>{step.label}</span>
                <span className="text-xs text-gray-400 mt-0.5">{step.subtitle}</span>
              </li>
            );
          })}
        </ol>
      </div>

      {/* Main Form Card */}
      <div className="w-full max-w-2xl bg-white shadow-xl rounded-2xl overflow-hidden">
        {/* Step Header (no icon) */}
        <div className="px-8 py-6 border-b border-gray-100 bg-gray-50">
          <h2 className="text-xl font-bold text-gray-900">
            {stepLabels[currentStep - 1].label}
          </h2>
          <p className="mt-1 text-sm text-gray-500">
            {stepLabels[currentStep - 1].subtitle}
          </p>
        </div>
        {/* Form Body */}
        <div className="p-8">
          {error && (
            <div className="mb-6 p-4 rounded-md bg-red-50 border border-red-200">
              <p className="text-sm text-red-600">{error}</p>
            </div>
          )}
          {message && (
            <div
              className={`mb-6 p-4 rounded-md ${
                message.type === 'success' ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'
              } border`}
            >
              <p className={`text-sm ${message.type === 'success' ? 'text-green-600' : 'text-red-600'}`}>
                {message.text}
              </p>
            </div>
          )}
          {renderStep()}
        </div>
      </div>
    </div>
  );
}
